import { registerSW } from 'virtual:pwa-register';
import { markOfflineReady, markOfflineUnavailable } from './offline';
import { markUpdateWaiting, setUpdateActivator } from './update';
import { checkForUpdatesWhenReopened, watchForWaitingVersion } from './updateChecks';

/**
 * Registers the Workbox service worker that keeps the app shell available offline (generated by
 * vite-plugin-pwa; see vite.config.ts). It only ever fetches the app's own files from its own
 * origin (e2e/build-output.spec.ts checks the built sw.js). With registerType 'prompt', a new
 * version waits until the person taps Reload.
 */
export function startServiceWorker(): void {
  if (!('serviceWorker' in navigator)) {
    markOfflineUnavailable();
    return;
  }
  const updateServiceWorker = registerSW({
    onNeedRefresh: markUpdateWaiting,
    onOfflineReady: markOfflineReady,
    // The app reloads itself, once, when the new version takes control (update.ts).
    onNeedReload: () => undefined,
    onRegisteredSW: (_url, registration) => {
      if (registration === undefined) return;
      // An active worker has finished saving its copy of every file.
      if (registration.active !== null) markOfflineReady();
      watchForWaitingVersion(registration);
      checkForUpdatesWhenReopened(registration);
    },
    onRegisterError: (error: unknown) => {
      markOfflineUnavailable();
      console.warn('The offline copy of the app could not be set up.', error);
    },
  });
  setUpdateActivator(() => updateServiceWorker(true));
  // Resolves once a service worker is active for the app: on a first visit, when the copy is saved.
  void navigator.serviceWorker.ready.then(markOfflineReady);
}
